function detail(label,value,color,denominator){const proportion=denominator>0?Math.abs(value)/denominator:0;return `<div class="detail-row"><span>${label}</span><strong style="color:${color}">${value>0?'+':''}${money(value,2)}</strong>${denominator&&Math.abs(value)>=.005?`<div class="track"><span style="background:${color};width:${Math.min(100,proportion*100)}%"></span></div><small>${pct(proportion)}</small>`:''}</div>`}
