function chartBounds(items,keepZero=false){let running=0;const steps=items.filter(x=>keepZero||x[2]||Math.abs(x[1])>=.005).map(([label,value,total,color])=>{const start=total?0:running;running=total?value:running+value;return {label,value,total,color,start,end:running}}),low=Math.min(...steps.map(b=>b.total?b.end:Math.min(b.start,b.end))),high=Math.max(1,...steps.map(b=>Math.max(b.start,b.end)));return {steps,low,high,floor:low>0?Math.max(0,low-Math.max((high-low)*.15,high*.02)):Math.min(0,low)}}
