document.addEventListener('click',e=>{if(e.target.id==='reset'){const year=currentYear();s=structuredClone(defaultScenario);s.year=year;s.annualSalary=benchmark(year,0).median;$('#dialog').close();route('salary');toast(t('Current calculation reset','当前计算已重置'))}});
function currentYear(){const k=today(),y=Number(k.slice(0,4))-(Number(k.slice(5,7))<7?1:0);return Math.max(2023,Math.min(2029,y))}
async function init(){try{[rules,holidayData,deductionCategories]=await Promise.all([fetch('./rules.json').then(res=>{if(!res.ok)throw Error('Rules unavailable');return res.json()}),fetch('./holidays.json').then(res=>{if(!res.ok)throw Error('Holidays unavailable');return res.json()}),fetch('./deduction-categories.json').then(res=>{if(!res.ok)throw Error('Categories unavailable');return res.json()})]);holidays=holidayData.holidays;try{const saved=JSON.parse(localStorage.getItem(storageKey)??'null');if(saved){if(['en','zh'].includes(saved.lang))lang=saved.lang;if(['purple','blue','orange','gold','lime','navy'].includes(saved.theme))theme=saved.theme;if(['light','dark'].includes(saved.appearance))appearance=saved.appearance;if(saved.w&&validWork({...w,...saved.w})&&saved.w.goalDeposits?.every(d=>Number.isFinite(d.amount)&&d.amount>0))w={...w,...saved.w};if(Array.isArray(saved.records))records=saved.records.filter(e=>/^\d{4}-\d{2}-\d{2}$/.test(e.dateKey)&&['work','annualLeave','sickLeave'].includes(e.kind)&&[e.paidMinutes,e.idleMinutes,e.overtimeMinutes,e.dailyCash,e.contractHourly].every(n=>Number.isFinite(n)&&n>=0)&&e.paidMinutes>0&&e.idleMinutes<=e.paidMinutes);if(Array.isArray(saved.scenarios))scenarios=saved.scenarios.filter(x=>x.inputs&&rules.some(r=>r.year===x.inputs.year)&&Number.isFinite(x.inputs.annualSalary)&&x.inputs.annualSalary>=0)}}catch{}s.year=currentYear();s.uninsuredDays=r().days;s.annualSalary=benchmark(s.year,0).median;anchor=today();tab=['salary','help','deductions','rates','work'].includes(location.hash.slice(1))?location.hash.slice(1):'salary';render()}catch{$('#main').innerHTML='<h1>Unable to load / 加载失败</h1><p>Please refresh your connection and try again. 请检查网络后刷新。</p>'}}
init();

document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-chart-bar]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
